const crypto=require("node:crypto");const{promisify}=require("node:util");const{pool,ready}=require("./db");const scrypt=promisify(crypto.scrypt);
async function hash(password){const salt=crypto.randomBytes(16).toString("hex");return salt+":"+(await scrypt(password,salt,64)).toString("hex")}
async function main(){const nama=String(process.env.ADMIN_NAME||"").trim(),email=String(process.env.ADMIN_EMAIL||"").trim().toLowerCase(),password=String(process.env.ADMIN_PASSWORD||"");if(!nama||!email.includes("@")||password.length<12)throw new Error("ADMIN_NAME, ADMIN_EMAIL valid, dan ADMIN_PASSWORD minimal 12 karakter wajib diisi");await ready;const existing=(await pool.query("SELECT * FROM users WHERE email=$1",[email])).rows[0];if(existing&&existing.account_type!=="admin")throw new Error("email sudah dipakai akun reguler");if(existing){await pool.query("UPDATE users SET nama=$1,aktif=TRUE,updated_at=now() WHERE id=$2",[nama,existing.id]);console.log("Admin siap: "+email)}else{await pool.query("INSERT INTO users(nama,email,password_hash,account_type) VALUES($1,$2,$3,'admin')",[nama,email,await hash(password)]);console.log("Admin dibuat: "+email)}}
main().catch(e=>{console.error(e.message);process.exitCode=1}).finally(()=>pool.end());
